(function() { 'use strict'; const CONFIG = { animationDuration: 300, typingSpeed: 50, counterDuration: 2000, scrollOffset: 80, observerThreshold: 0.1, apiBaseUrl: window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' ? 'http://localhost:8000' : 'https://api.codegraph.ru', apiTimeout: 180000 }; const MOCK_RESPONSES = { 'Как устроена авторизация?': { answer: 'Авторизация в PostgreSQL реализована в модуле src/backend/libpq/auth.c.\n\nОсновные функции:\n- ClientAuthentication() - точка входа\n- CheckPasswordAuth() - проверка пароля\n- CheckMD5Auth() - MD5 хеширование\n\nПоддерживаемые методы: trust, md5, scram-sha-256, cert, ldap.', processing_time_ms: 1250 }, 'Как работает MVCC в PostgreSQL?': { answer: 'MVCC (Multi-Version Concurrency Control) реализован через:\n\n1. xmin/xmax в заголовке каждого tuple\n2. Snapshot видимости (GetTransactionSnapshot)\n3. Visibility map для оптимизации\n\nКлючевые файлы: src/backend/access/heap/heapam.c, src/backend/storage/ipc/procarray.c', processing_time_ms: 1100 }, 'Покажи callers функции palloc': { answer: 'palloc() вызывается из 847 функций в кодовой базе.\n\nТоп-5 вызывающих модулей:\n- executor/ - 234 вызова\n- parser/ - 156 вызовов\n- rewriter/ - 89 вызовов\n- optimizer/ - 78 вызовов\n- utils/ - 67 вызовов', processing_time_ms: 890 }, 'default': { answer: 'CodeGraph анализирует кодовую базу PostgreSQL с использованием Code Property Graph.\n\nПопробуйте примеры из кнопок выше или задайте свой вопрос о коде.', processing_time_ms: 500 } }; const DOM = {}; function cacheDOM() { DOM.html = document.documentElement; DOM.body = document.body; DOM.header = document.querySelector('.header'); DOM.themeToggle = document.querySelector('.theme-toggle'); DOM.mobileMenuToggle = document.querySelector('.mobile-menu-toggle'); DOM.mobileNav = document.querySelector('.mobile-nav'); DOM.navLinks = document.querySelectorAll('.nav-link, .mobile-nav-link'); DOM.demoInput = document.getElementById('demo-input'); DOM.demoOutput = document.getElementById('demo-output'); DOM.demoCursor = document.querySelector('.demo-cursor'); DOM.demoExampleBtns = document.querySelectorAll('.demo-example-btn'); DOM.featureTabs = document.querySelectorAll('.feature-tab'); DOM.featurePanels = document.querySelectorAll('.features-panel'); DOM.faqItems = document.querySelectorAll('.faq-item'); DOM.faqSearch = document.querySelector('.faq-search-input'); DOM.faqCategoryBtns = document.querySelectorAll('.faq-category-btn'); DOM.integrationFilterBtns = document.querySelectorAll('.integration-filter-btn'); DOM.integrationCards = document.querySelectorAll('.integration-card'); DOM.pipelineSteps = document.querySelectorAll('.pipeline-step'); DOM.scenarioTabs = document.querySelectorAll('.scenario-tab'); DOM.counters = document.querySelectorAll('[data-count]'); DOM.progressBars = document.querySelectorAll('.quality-metric-bar-fill'); DOM.animatedElements = document.querySelectorAll('[data-animate]'); DOM.demoForm = document.getElementById('demo-form'); DOM.questionInput = document.getElementById('question-input'); DOM.askBtn = document.getElementById('ask-btn'); DOM.demoResult = document.getElementById('demo-result'); DOM.solutionExampleBtns = document.querySelectorAll('.solution .demo-example-btn, #solution .demo-example-btn'); } function initTheme() { const savedTheme = localStorage.getItem('theme'); const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches; const theme = savedTheme || (prefersDark ? 'dark' : 'light'); setTheme(theme); if (DOM.themeToggle) { DOM.themeToggle.addEventListener('click', toggleTheme); } window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', (e) => { if (!localStorage.getItem('theme')) { setTheme(e.matches ? 'dark' : 'light'); } }); } function setTheme(theme) { DOM.html.setAttribute('data-theme', theme); localStorage.setItem('theme', theme); } function toggleTheme() { const currentTheme = DOM.html.getAttribute('data-theme'); setTheme(currentTheme === 'dark' ? 'light' : 'dark'); } function initMobileNav() { if (!DOM.mobileMenuToggle || !DOM.mobileNav) return; DOM.mobileMenuToggle.addEventListener('click', () => { DOM.mobileMenuToggle.classList.toggle('active'); DOM.mobileNav.classList.toggle('open'); DOM.body.style.overflow = DOM.mobileNav.classList.contains('open') ? 'hidden' : ''; }); DOM.navLinks.forEach(link => { link.addEventListener('click', () => { DOM.mobileMenuToggle.classList.remove('active'); DOM.mobileNav.classList.remove('open'); DOM.body.style.overflow = ''; }); }); document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && DOM.mobileNav.classList.contains('open')) { DOM.mobileMenuToggle.classList.remove('active'); DOM.mobileNav.classList.remove('open'); DOM.body.style.overflow = ''; } }); } function initHeaderScroll() { if (!DOM.header) return; let lastScroll = 0; let ticking = false; window.addEventListener('scroll', () => { if (!ticking) { window.requestAnimationFrame(() => { const currentScroll = window.pageYOffset; if (currentScroll > 50) { DOM.header.classList.add('scrolled'); } else { DOM.header.classList.remove('scrolled'); } lastScroll = currentScroll; ticking = false; }); ticking = true; } }); } function initSmoothScroll() { document.querySelectorAll('a[href^="#"]').forEach(anchor => { anchor.addEventListener('click', function(e) { e.preventDefault(); const target = document.querySelector(this.getAttribute('href')); if (target) { const offsetTop = target.offsetTop - CONFIG.scrollOffset; window.scrollTo({ top: offsetTop, behavior: 'smooth' }); } }); }); } function initDemoTerminal() { if (!DOM.demoInput || !DOM.demoOutput) return; DOM.demoInput.addEventListener('keypress', (e) => { if (e.key === 'Enter') { e.preventDefault(); const query = DOM.demoInput.value.trim(); if (query) { runDemo(query); } } }); DOM.demoExampleBtns.forEach(btn => { btn.addEventListener('click', () => { const query = btn.getAttribute('data-query'); DOM.demoInput.value = query; runDemo(query); }); }); setTimeout(() => { if (DOM.demoExampleBtns.length > 0) { const firstQuery = DOM.demoExampleBtns[0].getAttribute('data-query'); typeText(DOM.demoInput, firstQuery, () => { setTimeout(() => runDemo(firstQuery), 500); }); } }, 1500); } async function runDemo(query) { animatePipeline(); DOM.demoOutput.innerHTML = '<span class="highlight">Анализирую...</span>'; if (DOM.demoCursor) DOM.demoCursor.style.display = 'inline-block'; try { const response = await fetchWithTimeout( `${CONFIG.apiBaseUrl}/api/v1/demo/chat`, { method: 'POST', headers: { 'Content-Type': 'application/json', }, body: JSON.stringify({ query: query, language: 'ru' }) }, CONFIG.apiTimeout ); if (response.status === 429) { DOM.demoOutput.innerHTML = '<span class="warning">Превышен лимит запросов. Подождите минуту.</span>'; if (DOM.demoCursor) DOM.demoCursor.style.display = 'none'; return; } if (!response.ok) { throw new Error(`API error: ${response.status}`); } const data = await response.json(); displayHeroDemoResult(data.answer); } catch (err) { console.warn('API call failed, using mock response:', err.message); const mockData = MOCK_RESPONSES[query] || MOCK_RESPONSES['default']; await new Promise(resolve => setTimeout(resolve, 800 + Math.random() * 400)); displayHeroDemoResult(mockData.answer); } } function displayHeroDemoResult(answer) { DOM.demoOutput.innerHTML = ''; const MAX_HERO_LENGTH = 300; let displayText = answer; let isTruncated = false; if (displayText.length > MAX_HERO_LENGTH) { displayText = displayText.substring(0, MAX_HERO_LENGTH).trim(); const lastSpace = displayText.lastIndexOf(' '); if (lastSpace > MAX_HERO_LENGTH - 50) { displayText = displayText.substring(0, lastSpace); } displayText += '...'; isTruncated = true; } typeHTML(DOM.demoOutput, escapeHtml(displayText), () => { if (DOM.demoCursor) DOM.demoCursor.style.display = 'none'; if (isTruncated) { const moreLink = document.createElement('a'); moreLink.href = '#solution'; moreLink.className = 'demo-more-link'; moreLink.textContent = ' Подробнее →'; moreLink.addEventListener('click', (e) => { e.preventDefault(); document.querySelector('#solution').scrollIntoView({ behavior: 'smooth' }); }); DOM.demoOutput.appendChild(moreLink); } }); } function typeText(element, text, callback) { let i = 0; element.value = ''; function type() { if (i < text.length) { element.value += text.charAt(i); i++; setTimeout(type, CONFIG.typingSpeed); } else if (callback) { callback(); } } type(); } function typeHTML(element, html, callback) { const tempDiv = document.createElement('div'); tempDiv.innerHTML = html; const text = tempDiv.textContent; let i = 0; let currentHTML = ''; function type() { if (i < html.length) { if (html[i] === '<') { const closeTag = html.indexOf('>', i); if (closeTag !== -1) { currentHTML += html.substring(i, closeTag + 1); i = closeTag + 1; } } else { currentHTML += html[i]; i++; } element.innerHTML = currentHTML; const delay = html[i - 1] === '\n' ? 100 : (Math.random() * 20 + 10); setTimeout(type, delay); } else if (callback) { callback(); } } type(); } function initSolutionDemo() { if (!DOM.questionInput || !DOM.demoResult) return; if (DOM.askBtn) { DOM.askBtn.addEventListener('click', () => { const query = DOM.questionInput.value.trim(); if (query) { runSolutionDemo(query); } }); } DOM.questionInput.addEventListener('keypress', (e) => { if (e.key === 'Enter') { e.preventDefault(); const query = DOM.questionInput.value.trim(); if (query) { runSolutionDemo(query); } } }); const exampleBtns = document.querySelectorAll('#solution .demo-example-btn'); exampleBtns.forEach(btn => { btn.addEventListener('click', () => { const query = btn.getAttribute('data-query'); DOM.questionInput.value = query; runSolutionDemo(query); }); }); } async function runSolutionDemo(query) { animatePipeline(); DOM.demoResult.innerHTML = '<div class="result-loading"><span class="spinner"></span> Анализирую...</div>'; try { const response = await fetchWithTimeout( `${CONFIG.apiBaseUrl}/api/v1/demo/chat`, { method: 'POST', headers: { 'Content-Type': 'application/json', }, body: JSON.stringify({ query: query, language: 'ru' }) }, CONFIG.apiTimeout ); if (response.status === 429) { showRateLimitError(); return; } if (!response.ok) { throw new Error(`API error: ${response.status}`); } const data = await response.json(); showApiResult(data.answer, data.processing_time_ms); } catch (err) { console.warn('API call failed, using mock response:', err.message); const mockData = MOCK_RESPONSES[query] || MOCK_RESPONSES['default']; await new Promise(resolve => setTimeout(resolve, 800 + Math.random() * 400)); showApiResult(mockData.answer, mockData.processing_time_ms); } } async function fetchWithTimeout(url, options, timeout) { const controller = new AbortController(); const timeoutId = setTimeout(() => controller.abort(), timeout); try { const response = await fetch(url, { ...options, signal: controller.signal }); clearTimeout(timeoutId); return response; } catch (err) { clearTimeout(timeoutId); throw err; } } function showApiResult(answer, processingTimeMs) { const timeStr = processingTimeMs ? ` <span class="processing-time">(${processingTimeMs.toFixed(0)}ms)</span>` : ''; DOM.demoResult.innerHTML = `<div class="result-content"><pre>${escapeHtml(answer)}</pre>${timeStr}</div>`; } function showRateLimitError() { DOM.demoResult.innerHTML = `<div class="result-error"> <span class="warning">Превышен лимит запросов (30/мин)</span> <p>Пожалуйста, подождите минуту и попробуйте снова.</p> </div>`; } function showApiError() { DOM.demoResult.innerHTML = '<div class="result-error"><span class="warning">API недоступен. Попробуйте позже.</span></div>'; } function escapeHtml(text) { const div = document.createElement('div'); div.textContent = text; return div.innerHTML; } function animatePipeline() { if (!DOM.pipelineSteps || DOM.pipelineSteps.length === 0) return; DOM.pipelineSteps.forEach(step => step.classList.remove('active')); DOM.pipelineSteps.forEach((step, index) => { setTimeout(() => { if (index > 0) { DOM.pipelineSteps[index - 1].classList.remove('active'); } step.classList.add('active'); }, index * 800); }); setTimeout(() => { DOM.pipelineSteps[DOM.pipelineSteps.length - 1].classList.add('active'); }, DOM.pipelineSteps.length * 800); } function initFeatureTabs() { if (!DOM.featureTabs || DOM.featureTabs.length === 0) return; DOM.featureTabs.forEach(tab => { tab.addEventListener('click', () => { const target = tab.getAttribute('data-tab'); DOM.featureTabs.forEach(t => t.classList.remove('active')); tab.classList.add('active'); DOM.featurePanels.forEach(panel => { panel.classList.remove('active'); if (panel.getAttribute('data-panel') === target) { panel.classList.add('active'); } }); }); }); } function initScenarioTabs() { if (!DOM.scenarioTabs || DOM.scenarioTabs.length === 0) return; DOM.scenarioTabs.forEach(tab => { tab.addEventListener('click', () => { const query = tab.getAttribute('data-query'); DOM.scenarioTabs.forEach(t => t.classList.remove('active')); tab.classList.add('active'); if (query && DOM.demoInput) { DOM.demoInput.value = query; runDemo(query); } }); }); } function initFAQ() { if (!DOM.faqItems || DOM.faqItems.length === 0) return; DOM.faqItems.forEach(item => { const question = item.querySelector('.faq-question'); if (question) { question.addEventListener('click', () => { item.classList.toggle('open'); const isNowOpen = item.classList.contains('open'); question.setAttribute('aria-expanded', String(isNowOpen)); }); } }); if (DOM.faqSearch) { DOM.faqSearch.addEventListener('input', (e) => { const query = e.target.value.toLowerCase(); DOM.faqItems.forEach(item => { const text = item.textContent.toLowerCase(); item.style.display = text.includes(query) ? '' : 'none'; }); }); } if (DOM.faqCategoryBtns) { DOM.faqCategoryBtns.forEach(btn => { btn.addEventListener('click', () => { const category = btn.getAttribute('data-category'); DOM.faqCategoryBtns.forEach(b => { b.classList.remove('active'); b.setAttribute('aria-pressed', 'false'); }); btn.classList.add('active'); btn.setAttribute('aria-pressed', 'true'); DOM.faqItems.forEach(item => { if (category === 'all') { item.style.display = ''; } else { const itemCategory = item.getAttribute('data-category'); item.style.display = itemCategory === category ? '' : 'none'; } }); }); }); } } function initIntegrationFilters() { if (!DOM.integrationFilterBtns || DOM.integrationFilterBtns.length === 0) return; DOM.integrationFilterBtns.forEach(btn => { btn.addEventListener('click', () => { const filter = btn.getAttribute('data-filter'); DOM.integrationFilterBtns.forEach(b => b.classList.remove('active')); btn.classList.add('active'); DOM.integrationCards.forEach(card => { if (filter === 'all') { card.style.display = ''; } else { const status = card.getAttribute('data-status'); card.style.display = status === filter ? '' : 'none'; } }); }); }); } function initCounters() { if (!DOM.counters || DOM.counters.length === 0) return; const observer = new IntersectionObserver((entries) => { entries.forEach(entry => { if (entry.isIntersecting) { animateCounter(entry.target); observer.unobserve(entry.target); } }); }, { threshold: CONFIG.observerThreshold }); DOM.counters.forEach(counter => observer.observe(counter)); } function animateCounter(element) { const target = parseInt(element.getAttribute('data-count'), 10); const suffix = element.getAttribute('data-suffix') || ''; const prefix = element.getAttribute('data-prefix') || ''; const duration = CONFIG.counterDuration; const start = performance.now(); function update(currentTime) { const elapsed = currentTime - start; const progress = Math.min(elapsed / duration, 1); const easeOut = 1 - Math.pow(1 - progress, 3); const current = Math.floor(easeOut * target); element.textContent = prefix + current + suffix; if (progress < 1) { requestAnimationFrame(update); } else { element.textContent = prefix + target + suffix; } } requestAnimationFrame(update); } function initProgressBars() { if (!DOM.progressBars || DOM.progressBars.length === 0) return; const observer = new IntersectionObserver((entries) => { entries.forEach(entry => { if (entry.isIntersecting) { const target = entry.target.getAttribute('data-progress') || '0'; entry.target.style.width = target + '%'; observer.unobserve(entry.target); } }); }, { threshold: CONFIG.observerThreshold }); DOM.progressBars.forEach(bar => observer.observe(bar)); } function initScrollAnimations() { if (!DOM.animatedElements || DOM.animatedElements.length === 0) return; const observer = new IntersectionObserver((entries) => { entries.forEach(entry => { if (entry.isIntersecting) { const animation = entry.target.getAttribute('data-animate'); entry.target.classList.add('animated', `animate-${animation}`); observer.unobserve(entry.target); } }); }, { threshold: CONFIG.observerThreshold, rootMargin: '0px 0px -50px 0px' }); DOM.animatedElements.forEach(el => observer.observe(el)); } function initFormValidation() { if (!DOM.demoForm) return; const validationMessages = { valueMissing: 'Пожалуйста, заполните это поле', typeMismatch: { email: 'Пожалуйста, введите корректный email адрес', url: 'Пожалуйста, введите корректный URL' }, patternMismatch: 'Пожалуйста, введите данные в правильном формате', tooShort: 'Минимальная длина: {minLength} символов', tooLong: 'Максимальная длина: {maxLength} символов' }; const formInputs = DOM.demoForm.querySelectorAll('input, select, textarea'); formInputs.forEach(input => { input.addEventListener('invalid', (e) => { const validity = input.validity; if (validity.valueMissing) { input.setCustomValidity(validationMessages.valueMissing); } else if (validity.typeMismatch) { const type = input.type; input.setCustomValidity(validationMessages.typeMismatch[type] || 'Неверный формат'); } else if (validity.patternMismatch) { input.setCustomValidity(validationMessages.patternMismatch); } else if (validity.tooShort) { input.setCustomValidity(validationMessages.tooShort.replace('{minLength}', input.minLength)); } else if (validity.tooLong) { input.setCustomValidity(validationMessages.tooLong.replace('{maxLength}', input.maxLength)); } }); input.addEventListener('input', () => { input.setCustomValidity(''); }); input.addEventListener('change', () => { input.setCustomValidity(''); }); }); DOM.demoForm.addEventListener('submit', async (e) => { e.preventDefault(); const inputs = DOM.demoForm.querySelectorAll('input[required], select[required]'); let isValid = true; inputs.forEach(input => { if (!input.value.trim()) { isValid = false; input.classList.add('error'); } else { input.classList.remove('error'); } }); const emailInput = DOM.demoForm.querySelector('input[type="email"]'); if (emailInput && emailInput.value) { const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/; if (!emailRegex.test(emailInput.value)) { isValid = false; emailInput.classList.add('error'); } } if (isValid) { const submitBtn = DOM.demoForm.querySelector('button[type="submit"]'); if (!submitBtn) return; const originalText = submitBtn.textContent; submitBtn.textContent = 'Отправка...'; submitBtn.disabled = true; const formData = { name: DOM.demoForm.querySelector('#name').value.trim(), email: DOM.demoForm.querySelector('#email').value.trim(), company: DOM.demoForm.querySelector('#company').value.trim(), position: DOM.demoForm.querySelector('#position')?.value.trim() || null, team_size: DOM.demoForm.querySelector('#team-size')?.value || null, language: DOM.demoForm.querySelector('#language')?.value || null, }; const isLocalhost = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1'; const leadsApiUrl = isLocalhost ? 'http://localhost:8001/api/v1/leads' : 'https://api.codegraph.ru/api/v1/leads'; try { const response = await fetch(leadsApiUrl, { method: 'POST', headers: { 'Content-Type': 'application/json', }, body: JSON.stringify(formData), }); if (response.ok) { submitBtn.textContent = 'Заявка отправлена!'; submitBtn.style.background = '#10B981'; DOM.demoForm.reset(); setTimeout(() => { submitBtn.textContent = originalText; submitBtn.style.background = ''; submitBtn.disabled = false; }, 3000); } else if (response.status === 429) { submitBtn.textContent = 'Слишком много запросов'; submitBtn.style.background = '#EF4444'; setTimeout(() => { submitBtn.textContent = originalText; submitBtn.style.background = ''; submitBtn.disabled = false; }, 3000); } else { throw new Error(`Server error: ${response.status}`); } } catch (error) { console.error('Form submission error:', error); submitBtn.textContent = 'Ошибка отправки'; submitBtn.style.background = '#EF4444'; setTimeout(() => { submitBtn.textContent = originalText; submitBtn.style.background = ''; submitBtn.disabled = false; }, 3000); } } }); } function initActiveNavigation() { const sections = document.querySelectorAll('section[id]'); if (sections.length === 0) return; const observer = new IntersectionObserver((entries) => { entries.forEach(entry => { if (entry.isIntersecting) { const id = entry.target.getAttribute('id'); DOM.navLinks.forEach(link => { link.classList.remove('active'); if (link.getAttribute('href') === `#${id}`) { link.classList.add('active'); } }); } }); }, { threshold: 0.3, rootMargin: '-80px 0px -50% 0px' }); sections.forEach(section => observer.observe(section)); } function initKeyboardNavigation() { document.addEventListener('keydown', (e) => { if (e.target.classList.contains('feature-tab') || e.target.classList.contains('scenario-tab') || e.target.classList.contains('faq-question')) { const parent = e.target.parentElement; const items = Array.from(parent.querySelectorAll('[role="tab"], .faq-question')); const currentIndex = items.indexOf(e.target); let newIndex; if (e.key === 'ArrowRight' || e.key === 'ArrowDown') { newIndex = (currentIndex + 1) % items.length; } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') { newIndex = (currentIndex - 1 + items.length) % items.length; } if (newIndex !== undefined) { e.preventDefault(); items[newIndex].focus(); items[newIndex].click(); } } }); } function initPerformanceOptimizations() { if ('loading' in HTMLImageElement.prototype) { const images = document.querySelectorAll('img[loading="lazy"]'); images.forEach(img => { img.src = img.dataset.src; }); } let prefetchedLinks = new Set(); document.querySelectorAll('a[href^="http"]').forEach(link => { link.addEventListener('mouseenter', () => { const href = link.getAttribute('href'); if (!prefetchedLinks.has(href)) { const prefetch = document.createElement('link'); prefetch.rel = 'prefetch'; prefetch.href = href; document.head.appendChild(prefetch); prefetchedLinks.add(href); } }, { once: true }); }); } function initAccessibility() { DOM.faqItems.forEach((item, index) => { const question = item.querySelector('.faq-question'); const answer = item.querySelector('.faq-answer'); if (question && answer) { question.setAttribute('aria-expanded', 'false'); question.setAttribute('aria-controls', `faq-answer-${index}`); answer.setAttribute('id', `faq-answer-${index}`); } }); DOM.featureTabs.forEach(tab => { tab.setAttribute('role', 'tab'); }); DOM.scenarioTabs.forEach(tab => { tab.setAttribute('role', 'tab'); }); } window.onerror = function(msg, url, lineNo, columnNo, error) { console.error('Error: ', msg, '\nURL: ', url, '\nLine: ', lineNo); return false; }; function init() { cacheDOM(); initTheme(); initMobileNav(); initHeaderScroll(); initSmoothScroll(); initDemoTerminal(); initSolutionDemo(); initFeatureTabs(); initScenarioTabs(); initFAQ(); initIntegrationFilters(); initCounters(); initProgressBars(); initScrollAnimations(); initFormValidation(); initActiveNavigation(); initKeyboardNavigation(); initPerformanceOptimizations(); initAccessibility(); console.log('CodeGraph Landing Page initialized'); } if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); } else { init(); } })();